    by_name = {"cloud-services": "core-services", "cloud-core": "core-cloud", "cloud-vyos": "core-vyos",
               "cloud-s2s": "core-s2s", "one-core": "core-kvm", "data-nfs": "nfs", "data-iscsi": "iscsi"}
